import{_ as a,a as n,b as p,c as l,d as t}from"./chunks/asc_copy_l12l0_trans_b32_example2.CVeYvRuh.js";import{_ as c,a as e,b as i}from"./chunks/asc_copy_l12l0_trans_b4_example2.DIW787nS.js";import{_,o as d,a as r,b as o}from"./app.DlhOLPn6.js";const k=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"废弃接口","link":"/api/SIMD-API/c_api/deprecated_interface/deprecated_interface"},{"text":"asc_copy_l12l0b_trans_sync_arch_3510（废弃）","link":"/api/SIMD-API/c_api/deprecated_interface/asc_copy_l12l0b_trans_sync_arch_3510_deprecated"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/deprecated_interface/asc_copy_l12l0b_trans_sync_arch_3510_deprecated.md","filePath":"api/SIMD-API/c_api/deprecated_interface/asc_copy_l12l0b_trans_sync_arch_3510_deprecated.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":3,"title":"dtype支持的数据类型","slug":"dtype支持的数据类型","link":"#dtype支持的数据类型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"流水类型","slug":"流水类型","link":"#流水类型"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788934281000}'),h={name:"api/SIMD-API/c_api/deprecated_interface/asc_copy_l12l0b_trans_sync_arch_3510_deprecated.md"};function f(g,s,u,w,m,v){return d(),r("div",null,[...s[0]||(s[0]=[o('<div><article class="markdown-body"><h1>asc_copy_l12l0b_trans_sync_arch_3510（废弃）</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>头文件路径为：<code>&quot;c_api/composite/cube_datamove_composite.h&quot;</code>。</p><p><strong><code>asc_copy_l12l0b_trans_sync</code>接口已废弃，请使用<a href="../cube_datamove/asc_copy_l12l0b_trans/asc_copy_l12l0b_trans_arch_3510.html">对应的非同步接口</a>和同步接口<a href="../sync/asc_sync.html">asc_sync</a>替代。</strong></p><p>该接口实现带转置的2D格式数据从L1 Buffer到L0B Buffer的加载。</p><p>下面通过示例来讲解接口功能和关键参数：下文图中一个N形或者一个Z形代表一个分形。</p><ul><li>对于uint8_t/int8_t数据类型，每次迭代处理32 × 32 × 1B数据，可处理2个分形（一个分形512B），每次迭代中，源操作数中2个连续的16 × 32分形将被合并为1个32 × 32的方块矩阵，基于方块矩阵做转置，转置后分裂为2个16 × 32分形，根据目的操作数分形间隔等参数可以有不同的排布。</li></ul><p>如下图示例：</p><ul><li>共处理3072B的数据，每次迭代处理32 × 32 × 1B数据，需要3次迭代可以完成，repeat_time = 3；</li><li>src_stride = 1，表示相邻迭代间，源操作数前一个方块矩阵与后一个方块矩阵起始地址的间隔为1（单位：32 × 32 × 1B），这里的单位实际上是拼接后的方块矩阵的大小；</li><li>dst_gap = 1，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址到下一个迭代第一个分形起始地址的间隔为1（单位：512B）；</li><li>dst_frac_gap = 0，表示每个迭代内目的操作数前一个分形的结束地址与后一个分形起始地址的间隔为0（单位：512B）。 <img src="'+a+'" alt></li></ul><p>如下图示例：</p><ul><li><p>repeat_time和src_stride的解释和上图示例一致。</p></li><li><p>dst_gap = 0，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址和下一个迭代第一个分形起始地址无间隔。</p></li><li><p>dst_frac_gap = 2，表示每个迭代内目的操作数前一个分形的结束地址与后一个分形起始地址的间隔为2（单位：512B）。 <img src="'+n+'" alt></p></li><li><p>对于half/bfloat16_t数据类型，每次迭代处理16 × 16 × 2B数据，可处理1个分形（一个分形512B），每次迭代中，源操作数中1个16 × 16分形将被转置。</p><ul><li>因为每次迭代处理16 × 16 × 2B数据，需要3次迭代可以完成，repeat_time = 3；</li><li>src_stride = 1，表示相邻迭代间，源操作数前一个方块矩阵与后一个方块矩阵起始地址的间隔为1 （单位：16 × 16 × 2B）；</li><li>dst_gap = 0，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址到下一个迭代第一个分形起始地址无间隔；</li><li>该场景下，因为其分形即为方块矩阵，每个迭代处理一个分形，不存在迭代内分形的间隔，该参数设置无效。 <img src="'+p+'" alt></li></ul></li><li><p>对于float/int32_t/uint32_t数据类型，每次迭代处理16 × 16 × 4B数据，可处理2个分形（一个分形512B），每次迭代中，源操作数2个连续的16 × 8分形将被合并为1个16 × 16的方块矩阵，基于方块矩阵做转置，转置后分裂为2个16 × 8分形，根据目的操作数分形间隔等参数可以有不同的排布。 如下图示例：</p><ul><li>因为每次迭代处理16 × 16 × 4B数据，需要3次迭代可以完成，repeat_time = 3；</li><li>src_stride = 1，表示相邻迭代间，源操作数前一个方块矩阵与后一个方块矩阵起始地址的间隔为1（单位：16 × 16 × 4B），这里的单位实际上是拼接后的方块矩阵的大小；</li><li>dst_gap = 1，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址到下一个迭代第一个分形起始地址的间隔为1（单位：512B）；</li><li>dst_frac_gap = 0，表示每个迭代内目的操作数前一个分形结束地址与后一个分形起始地址的间隔为0（单位：512B）。 <img src="'+l+'" alt></li></ul></li></ul><p>如下图示例：</p><ul><li><p>repeat_time和src_stride的解释和上图示例一致。</p></li><li><p>dst_gap = 0，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址和下一个迭代第一个分形起始地址无间隔。</p></li><li><p>dst_frac_gap = 2，表示每个迭代内目的操作数前一个分形结束地址与后一个分形起始地址的间隔为2（单位：512B）。 <img src="'+t+'" alt></p></li><li><p>对于int4b_t数据类型，每次迭代处理64*64*0.5B数据，可处理4个分形（一个分形512B），每次迭代中，源操作数中4个连续的16*64分形将被合并为1个64*64的方块矩阵，基于方块矩阵做转置，转置后分裂为4个16*64分形，根据目的操作数分形间隔等参数可以有不同的排布。</p><p>int4b_t数据类型需要两个数拼成一个int8_t或uint8_t的数，拼凑的规则如下：</p><p><img src="'+c+'" alt></p><p>如下图所示：</p><ul><li>共需要处理6144B的数据，每次迭代处理64*64*0.5B数据，需要3次迭代可以完成，repeat_time = 3；</li><li>src_stride = 1，表示相邻迭代间，源操作数前一个方块矩阵与后一个方块矩阵起始地址的间隔为1（单位：64*64*0.5B），这里的单位实际上是拼接后的方块矩阵的大小；</li><li>dst_gap = 1，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址到下一个迭代第一个分形起始地址的间隔为1（单位：512B）；</li><li>dst_frac_gap = 0，表示每个迭代内目的操作数前一个分形的结束地址与后一个分形起始地址的间隔为0（单位：512B）。</li></ul><p><img src="'+e+'" alt></p><p>如下图示例：</p><ul><li>repeat_time和src_stride的解释和上图示例一致。</li><li>dst_gap = 0，表示相邻迭代间，目的操作数前一个迭代第一个分形的结束地址和下一个迭代第一个分形起始地址无间隔。</li><li>dst_frac_gap = 2，表示每个迭代内目的操作数前一个分形的结束地址与后一个分形起始地址的间隔为2（单位：512B）。</li></ul><p><img src="'+i+`" alt></p></li></ul><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 占位符形式</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">asc_copy_l12l0b_trans_sync</span><span class="p">(</span><span class="n">__cb__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span>
<span class="w">                                                  </span><span class="n">__cbuf__</span><span class="w"> </span><span class="o">&lt;</span><span class="n">dtype</span><span class="o">&gt;*</span><span class="w"> </span><span class="n">src</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">index_id</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeat</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_frac_gap</span><span class="p">,</span>
<span class="w">                                                  </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_frac_gap</span><span class="p">)</span>
</code></pre></div><h3 id="dtype支持的数据类型">dtype支持的数据类型<a class="header-anchor" href="#dtype支持的数据类型">​</a></h3><p>dtype支持的数据类型为<code>int4b_t</code>、<code>int8_t</code>、<code>uint8_t</code>、<code>fp4x2_e2m1_t</code>、<code>fp4x2_e1m2_t</code>、<code>hifloat8_t</code>、<code>fp8_e5m2_t</code>、<code>fp8_e4m3fn_t</code>、<code>half</code>、<code>bfloat16_t</code>、<code>int32_t</code>、<code>uint32_t</code>、<code>float</code>。</p><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th align="left">参数名</th><th align="left">输入/输出</th><th align="left">描述</th></tr></thead><tbody><tr><td align="left">dst</td><td align="left">输出</td><td align="left">目的L0B Buffer地址。</td></tr><tr><td align="left">src</td><td align="left">输入</td><td align="left">源L1 Buffer地址。</td></tr><tr><td align="left">index_id</td><td align="left">输入</td><td align="left">矩阵ID，搬运起始位置为源操作数中第几个分形。取值范围：[0, 65535]。</td></tr><tr><td align="left">repeat</td><td align="left">输入</td><td align="left">迭代次数。<br> 对于位宽为4的数据类型，每次迭代处理4个分形，每个分形为16*64*0.5B数据；<br> 对于位宽为8的数据类型，每次迭代处理2个分形，每个分形为16*32*1B数据；<br>对于位宽为16的数据类型，每次迭代处理1个分形，每个分形为16*16*2B数据；对于位宽为32的数据类型，每次迭代处理4个分形，每个分形为16*8*4B数据。取值范围：[1, 255]。</td></tr><tr><td align="left">src_stride</td><td align="left">输入</td><td align="left">相邻迭代间，源操作数前一个分形与后一个分形起始地址的间隔。单位为单个分形512B。取值范围：[0, 65535]。</td></tr><tr><td align="left">dst_gap</td><td align="left">输入</td><td align="left">相邻迭代间，目的操作数前一个分形结束地址与后一个分形起始地址的间隔。单位为单个分形512B。取值范围：[0, 65535]。</td></tr><tr><td align="left">dst_frac_gap</td><td align="left">输入</td><td align="left">每个迭代内目的操作数转置前一个分形结束地址与后一个分形起始地址的间隔。单位为512B。仅在数据位宽为4、8或32时有效。</td></tr><tr><td align="left">src_frac_gap</td><td align="left">输入</td><td align="left">每个迭代内源操作数转置前一个分形结束地址与后一个分形起始地址的间隔。单位为512B。仅在数据位宽为4、8或32时有效。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="流水类型">流水类型<a class="header-anchor" href="#流水类型">​</a></h2><p>PIPE_MTE1</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li>各存储单元的空间大小和对齐要求请参考<a href="../general_description_and_constraints.html#%E5%AD%98%E5%82%A8%E5%8D%95%E5%85%83%E8%AF%B4%E6%98%8E">存储单元说明</a>。</li><li>repeat=0表示不执行搬运操作。</li><li>开发者需要保证目的操作数转置后的分形没有重叠。</li><li>操作数地址重叠约束请参考<a href="../general_description_and_constraints.html#%E9%80%9A%E7%94%A8%E5%9C%B0%E5%9D%80%E9%87%8D%E5%8F%A0%E7%BA%A6%E6%9D%9F">通用地址重叠约束</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">//设置源操作数和目的操作数，total_length指参与计算的数据长度</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint64_t</span><span class="w"> </span><span class="n">total_length</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">512</span><span class="p">;</span>
<span class="n">__cbuf__</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">src</span><span class="p">[</span><span class="n">total_length</span><span class="p">];</span>
<span class="n">__cb__</span><span class="w"> </span><span class="kt">int32_t</span><span class="w"> </span><span class="n">dst</span><span class="p">[</span><span class="n">total_length</span><span class="p">];</span>

<span class="c1">// 设置搬运过程中的配置</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">n</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">64</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">nBlockSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="kt">uint8_t</span><span class="w"> </span><span class="n">repeat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">n</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="n">nBlockSize</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">index_id</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_stride</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_gap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">1</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">dst_frac_gap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">15</span><span class="p">;</span>
<span class="kt">uint16_t</span><span class="w"> </span><span class="n">src_frac_gap</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">8</span><span class="p">;</span>

<span class="n">asc_copy_l12l0b_trans_sync</span><span class="p">(</span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">index_id</span><span class="p">,</span><span class="w"> </span><span class="n">repeat</span><span class="p">,</span><span class="w"> </span><span class="n">src_stride</span><span class="p">,</span><span class="w"> </span><span class="n">dst_gap</span><span class="p">,</span><span class="w"> </span><span class="n">dst_frac_gap</span><span class="p">,</span><span class="w"> </span><span class="n">src_frac_gap</span><span class="p">);</span>
</code></pre></div></article></div>`,1)])])}const y=_(h,[["render",f]]);export{k as __pageData,y as default};
